const headers = {
  'Content-Type': 'application/json',
};

const BASE_URL = 'https://cri-test.zplan.qq.com';

/**
 * 拉取允许开启「二次分享」开关的 OpenID 白名单。
 * 返回 undefined 表示请求失败 / 未授权，调用方应视作未通过白名单。
 */
export const getOpenidConfig = async (): Promise<string[] | void> => {
  try {
    const rsp = await fetch(`${BASE_URL}/mini_app/get_openid_config`, {
      method: 'GET',
      headers,
    });
    const res = await rsp.json();
    console.log('getOpenidConfig res', res);
    return res.data;
  } catch (error) {
    console.error('getOpenidConfig', error);
  }
};
